import {icon,esc} from './icons.mjs';

const $=selector=>document.querySelector(selector);
const pageNames={overview:'运行概览',inbounds:'入站节点',routes:'路由管理',outbounds:'落地出口',users:'用户管理',logs:'活动日志',settings:'面板设置'};
const defaultTLSDomains=['www.cloudflare.com','www.apple.com','www.microsoft.com'];
const tlsPresets=()=>state.config.settings.tlsDomains?.length?state.config.settings.tlsDomains:defaultTLSDomains;
let authEpoch=0,updateState=null,updateTimer=null,updateStarted=0,updateChecked=false;
function showVersion(version){document.querySelectorAll('[data-build-version]').forEach(el=>el.textContent=version==='dev'?'开发构建':version||'版本未知');}
const updating=()=>['queued','downloading','installing'].includes(updateState?.progress?.phase);
function updateSection(){const u=updateState,p=u?.progress||{},active=updating(),latest=u?.latest||'尚未检查';return `<section class="settings-section"><h2>版本与更新</h2><dl class="kv-list"><div><dt>当前运行版本</dt><dd>${esc(u?.current||state.version||'dev')}</dd></div><div><dt>最新正式版本</dt><dd>${esc(latest)}</dd></div><div><dt>上次检查</dt><dd>${u?.checkedAt&&!u.checkedAt.startsWith('0001')?time(u.checkedAt):'尚未检查'}</dd></div></dl><div class="update-actions">${button(icon('refresh',13)+'检查更新','check-update')}${u?.available&&u.supported&&!active?button('一键更新到 '+esc(u.latest),'open-update','','primary'):''}${u?.latest?`<a class="telegram-link" href="${esc(u.releaseURL)}" target="_blank" rel="noopener noreferrer">发布说明</a>`:''}</div>${u?.error?info(esc(u.error),'alert'):''}${u?.reason?info(esc(u.reason)):''}${p.message?info(esc(p.message),p.phase==='failed'?'alert':'info'):''}${u&&!u.error&&u.latest&&!u.available?'<p class="field-hint">'+(u.current==='dev'?'开发构建不参与正式版本比较。':'当前已是最新版本或高于最新正式版本。')+'</p>':''}<p class="field-hint">更新保留端口、账号密码、证书和全部代理数据，不再显示安装设置。下载并校验完成后重启服务，TG 连接短暂断开，完成后需重新登录。</p></section>`;}
function paintUpdate(){const notice=$('#update-notice');if(notice){notice.hidden=!updateState?.available;notice.textContent='新版 '+(updateState?.latest||'');}const target=$('#update-panel');if(target)target.innerHTML=updateSection();}
async function loadUpdate(check=false){updateState=await api(check?'update/check':'update',check?{method:'POST'}:{});paintUpdate();if(updating())watchUpdate();}
function watchUpdate(){if(updateTimer)return;updateStarted=Date.now();updateTimer=setInterval(async()=>{if(Date.now()-updateStarted>600000){clearInterval(updateTimer);updateTimer=null;toast('更新状态等待超时，请在服务器查看 journalctl -u tg-relay-update',true);return;}try{const response=await fetch('/api/update',{credentials:'same-origin'});if(response.status===401){const auth=await fetch('/api/auth',{credentials:'same-origin'}).then(r=>r.json());showVersion(auth.version);if(auth.version===(updateState.progress?.target||updateState.latest)&&auth.ready&&auth.updatePhase==='complete'){clearInterval(updateTimer);updateTimer=null;showAuth(true);toast('更新完成，请重新登录');}else if(auth.updatePhase==='failed'){clearInterval(updateTimer);updateTimer=null;showAuth(true);toast('更新失败，请重新登录查看原因；也可运行 tg 检查服务。',true);}else if(state)showAuth(true);return;}if(!response.ok)return;updateState=await response.json();paintUpdate();if(!updating()){clearInterval(updateTimer);updateTimer=null;if(updateState.progress.phase==='complete')toast('更新完成，请重新登录');}}catch{if($('#update-panel'))$('#update-panel').innerHTML=info('服务正在更新或重启，正在等待恢复连接…');}},2000);}
let state=null,page='inbounds',query='',filter='all',previousFocus=null,toastTimer,busy=false,history=[];
const drafts=new Map(),formStates=new WeakMap();
const formValues=form=>Array.from(new FormData(form).entries());
const dirty=form=>!!form&&formStates.has(form)&&JSON.stringify(formValues(form))!==formStates.get(form).baseline;
function remember(form){if(dirty(form))drafts.set(formStates.get(form).key,formValues(form));}
function mountForm(form){
  if(!form||['login-form','setup-form'].includes(form.id))return;
  const key=`${form.id}:${form.elements.entityID?.value||form.elements.inboundID?.value||'new'}`;
  formStates.set(form,{key,baseline:JSON.stringify(formValues(form))});
  const draft=drafts.get(key);if(!draft)return;
  for(const input of form.elements){if(!input.name||input.type==='submit'||input.type==='button')continue;const values=draft.filter(([name])=>name===input.name).map(([,value])=>value);if(['checkbox','radio'].includes(input.type))input.checked=values.includes(input.value);else if(values.length)input.value=values[0];}
  const notice=document.createElement('div');notice.innerHTML=info('已恢复本次登录中未保存的草稿，请核对后保存。');(form.querySelector('.dialog-body')||form).prepend(notice);
}
function leave(action,form=$('form.dialog')||$('#settings-form')){
  if(busy)return;
  if(!dirty(form)){action();return;}
  if($('#unsaved-guard'))return;
  const focus=document.activeElement,base=$('.overlay'),guard=document.createElement('div');
  guard.id='unsaved-guard';guard.className='overlay';guard.innerHTML=`<section class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="unsaved-title" aria-describedby="unsaved-description"><div class="dialog-header"><div><h2 id="unsaved-title">还有未保存的修改</h2><p id="unsaved-description">可以继续编辑，或暂存草稿后离开。草稿仅在本次登录内保留，刷新页面后会丢失。</p></div></div><div class="dialog-footer">${button('放弃修改','discard-draft','','ghost')}${button('保留草稿并离开','keep-draft')}${button('继续编辑','stay-draft','','primary')}</div></section>`;
  if(base)base.inert=true;else{$('.shell').inert=true;$('.sidebar').inert=true;}
  $('#overlay-root').append(guard);
  guard.querySelector('[data-action="stay-draft"]').focus();
  guard.addEventListener('click',event=>{const choice=event.target.closest('[data-action]')?.dataset.action;if(!['discard-draft','keep-draft','stay-draft'].includes(choice))return;event.stopPropagation();guard.remove();if(base)base.inert=false;else{$('.shell').inert=false;$('.sidebar').inert=false;}if(choice==='stay-draft'){if(focus?.isConnected)focus.focus();return;}const meta=formStates.get(form);if(choice==='keep-draft')remember(form);else drafts.delete(meta.key);meta.baseline=JSON.stringify(formValues(form));action();});
}
const node=id=>state.config.inbounds.find(v=>v.id===id);
const outbound=id=>state.config.outbounds.find(v=>v.id===id);
const route=id=>state.config.routes.find(v=>v.id===id);
const user=id=>state.config.users.find(v=>v.id===id);
const credentials=(nid,uid)=>state.config.credentials.filter(v=>(!nid||v.inboundID===nid)&&(!uid||v.userID===uid));
const usage=(kind,id)=>state.usage[`${kind}:${id}`]||{upload:0,download:0};
const total=u=>(u?.upload||0)+(u?.download||0);
const bytes=value=>{const units=['B','KB','MB','GB','TB'];let n=Number(value)||0,i=0;while(n>=1024&&i<4){n/=1024;i++;}return `${n.toLocaleString('en-US',{maximumFractionDigits:i?1:0})} ${units[i]}`;};
const speed=value=>`${((Number(value)||0)*8/1e6).toFixed(2)} Mbps`;
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
const status=(value,text)=>`<span class="status ${value}"><span class="dot"></span>${esc(text||({running:'运行中',warning:'待配置',paused:'已停用',offline:'未启动'}[value]))}</span>`;
const time=value=>value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'short',timeStyle:'medium',timeZone:'Asia/Shanghai'}).format(new Date(value)):'—';
function expiryDate(value){if(!value)return '';return new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Shanghai'}).format(new Date(Date.parse(value)-1));}
function dateToExpiry(value){return value?new Date(Date.parse(`${value}T00:00:00+08:00`)+86400000).toISOString():'';}
function theme(value){document.documentElement.dataset.theme=value;document.querySelectorAll('[data-theme-option]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeOption===value)));try{localStorage.setItem('tg-relay-theme',value);}catch{}}
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
document.querySelectorAll('[data-theme-option]').forEach(b=>b.addEventListener('click',()=>theme(b.dataset.themeOption)));
theme(document.documentElement.dataset.theme);

async function api(path,options={}){
  const response=await fetch(`/api/${path}`,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(state&&options.method&&options.method!=='GET'?{'If-Match':String(state.config.revision)}:{}),...options.headers}});
  let data;try{data=await response.json();}catch{throw new Error('服务响应无效，请确认通过 TG Relay 程序打开面板。');}
  if(response.status===409&&state){close();await refresh();throw new Error('配置已被其他会话修改，已刷新，请重新编辑。');}
  if(!response.ok){if(response.status===401&&path!=='login')showAuth(true);throw new Error(data.error||`请求失败 (${response.status})`);}
  return data;
}
async function refresh(renderPage=true){
  const epoch=authEpoch,result=await api('state');if(epoch!==authEpoch)return;state=result;showVersion(state.version);const last=history.at(-1);if(!last||Date.now()-last.at>1500){history.push({at:Date.now(),up:state.uploadRate,down:state.downloadRate});if(history.length>60)history.shift();}
  document.body.dataset.authenticated='true';$('.workspace>span:nth-child(2)').innerHTML=`${esc(state.config.settings.workspace)}<small>管理面板 · 已连接</small>`;$('#nav-count').textContent=state.config.inbounds.length;if(renderPage)render();if(!updateChecked){updateChecked=true;loadUpdate(true).catch(()=>{});}
}
function toast(message,isError=false){clearTimeout(toastTimer);$('#toast').innerHTML=icon(isError?'alert':'check',16)+`<span>${esc(message)}</span>`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function heading(title,description,actions='',count){return `<div class="page-heading"><div><div class="eyebrow">TELEGRAM NETWORK CONTROL</div><div class="heading-line"><h1>${title}</h1>${count===undefined?'':`<span class="count-badge">${count}</span>`}</div><p class="page-description">${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function empty(title,description='',actions=''){return `<div class="empty-state">${icon('layers',26)}<strong>${title}</strong><p>${description}</p>${actions}</div>`;}
function footer(count){return `<div class="table-footer"><span>共 ${count} 条记录</span><span>数据来自当前内核运行状态</span></div>`;}
function field(label,name,value='',options={}){return `<label class="form-field ${options.full?'full':''}"><span class="field-label">${label}${options.required?'<span class="required">*</span>':''}</span><input name="${name}" value="${esc(value)}" type="${options.type||'text'}" ${options.hint?`aria-describedby="hint-${name}"`: ''} ${options.required?'required':''} ${options.min===undefined?'':`min="${options.min}"`} ${options.step?`step="${options.step}"`:""} ${options.max===undefined?'':`max="${options.max}"`} ${options.placeholder?`placeholder="${esc(options.placeholder)}"`:''} ${options.autocomplete?`autocomplete="${options.autocomplete}"`:''}>${options.hint?`<p id="hint-${name}" class="field-hint">${options.hint}</p>`:''}</label>`;}
function checkbox(label,name,checked=true,hint=''){return `<label class="switch-line"><span>${label}${hint?`<small>${hint}</small>`:''}</span><input type="checkbox" name="${name}" class="toggle" ${checked?'checked':''}></label>`;}
function info(message,ico='info'){return `<div class="info-message"><span>${icon(ico,15)}</span><span>${message}</span></div>`;}
function stats(){const n=state.config.inbounds,connections=Object.values(state.nodes).reduce((sum,v)=>sum+v.connections,0),all=usage('total','all');const card=(label,value,foot,ico)=>`<div class="stat-card stat-${ico}"><div class="stat-label"><span>${label}</span><span class="stat-icon">${icon(ico,16)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;return `<div class="stats-grid">${card('入站节点',n.length,`${n.filter(v=>v.enabled).length} 个启用 · ${n.filter(v=>!v.enabled).length} 个停用`,'inbound')}${card('当前连接',connections,`${state.config.users.filter(v=>v.enabled).length} 位已启用用户`,'activity')}${card('累计流量',bytes(total(all)),`↑ ${bytes(all.upload)} / ↓ ${bytes(all.download)}`,'download')}${card('实时速率',speed(state.uploadRate+state.downloadRate),`↑ ${speed(state.uploadRate)} / ↓ ${speed(state.downloadRate)}`,'switch')}</div>`;}
function routeSummary(n){const runtime=state.nodes[n.id]||{},r=route(runtime.routeID),o=outbound(runtime.outboundID);if(!r)return `<div class="route-name muted">未匹配路由</div><div class="route-sub">连接将被拒绝</div>`;return `<div class="route-name route-label">${icon('routes',13)} ${esc(r.name)}</div><div class="route-sub">${icon('arrow',10)} ${r.direct?'直连 Telegram':o?esc(o.name):'出口已停用'}</div>`;}
function nodesTable(list){if(!list.length)return empty('还没有匹配的入站','创建一个入站，再通过路由指定落地。');return `<div class="table-scroll"><table><thead><tr><th>入站节点</th><th>状态</th><th>路由 / 落地</th><th>用户</th><th>连接数</th><th>累计流量</th><th>操作</th></tr></thead><tbody>${list.map(n=>{const rt=state.nodes[n.id]||{status:'offline',connections:0};return `<tr><td><div class="node-identity"><span class="node-icon">${icon('inbound')}</span><div><div class="node-title">${esc(n.name)}</div><div class="node-sub"><span class="mono">:${n.port}</span><span class="protocol-tag">FAKE TLS</span></div></div></div></td><td>${status(rt.status)}${rt.error?`<div class="route-sub">${esc(rt.error)}</div>`:''}</td><td>${routeSummary(n)}</td><td class="number-cell">${credentials(n.id).length}</td><td class="number-cell">${rt.connections}${rt.retiringConnections?`<div class="route-sub">${rt.retiringConnections} 条旧路由连接</div>`:''}</td><td class="number-cell">${bytes(total(usage('inbound',n.id)))}</td><td><div class="row-actions">${button('管理','manage',n.id)}${button(icon('routes',12)+'路由','node-route',n.id,'ghost')}<button type="button" class="icon-button ghost" aria-label="查看${esc(n.name)}的用户链接" data-action="node-links" data-id="${n.id}">${icon('link',13)}</button></div></td></tr>`;}).join('')}</tbody></table></div>`;}
function filteredNodes(){return state.config.inbounds.filter(n=>{const rt=state.nodes[n.id]||{},r=route(rt.routeID),o=outbound(rt.outboundID);return (filter==='all'||rt.status===filter)&&`${n.name} ${n.port} ${r?.name||''} ${o?.name||''}`.toLowerCase().includes(query.toLowerCase());});}
function nodeResults(){const list=filteredNodes();return nodesTable(list)+footer(list.length);}
function renderInbounds(){return `${heading('入站节点','固定 TG 入口，由路由选择直连或落地转发。',button(icon('refresh',13)+'刷新','refresh')+button(icon('plus',14)+'新建入站','edit-inbound','','primary'),state.config.inbounds.length)}${stats()}<section class="panel"><div class="panel-title-row"><div><h2>全部入站</h2><div class="subtext">入站 → 路由规则 → 落地出口</div></div>${button('管理路由 '+icon('arrow',12),'go-routes','','link-button')}</div><div class="table-toolbar"><label class="search-wrap"><span>${icon('search',14)}</span><input id="search-input" type="search" aria-label="搜索入站节点" placeholder="搜索名称、端口、路由或落地…" value="${esc(query)}"></label><select id="status-filter" aria-label="筛选节点状态"><option value="all">全部状态</option><option value="running">运行中</option><option value="warning">待配置</option><option value="paused">已停用</option><option value="offline">未启动</option></select></div><div id="node-results">${nodeResults()}</div></section><div class="connection-note"><span class="note-icon">${icon('link',16)}</span><div><strong>调整路由或落地，TG 链接保持不变</strong><p>入口地址、端口及用户密钥保持不变时，用户无需重新添加链接。</p></div>${button('切换说明 '+icon('arrow',12),'explain','','ghost')}</div>`;}
function renderRoutes(){const ordered=[...state.config.routes].sort((a,b)=>a.priority-b.priority||a.id.localeCompare(b.id));return `${heading('路由管理','按入站匹配规则，再选择直连或落地出口；优先级数字越小越先匹配。',button(icon('plus',14)+'新建路由','edit-route','','primary'),ordered.length)}<div class="routing-guide"><span>${icon('inbound',20)}<strong>入站节点</strong><small>以入站标签匹配</small></span>${icon('arrow',19)}<span class="routing-guide-active">${icon('routes',20)}<strong>路由规则</strong><small>优先级与启用状态</small></span>${icon('arrow',19)}<span>${icon('outbound',20)}<strong>落地出口</strong><small>直连 / SOCKS5 / HTTP / HTTPS</small></span></div><section class="panel"><div class="panel-title-row"><div><h2>转发规则</h2><div class="subtext">第一条匹配的启用规则生效。匹配出口不可用时拒绝连接。</div></div></div>${ordered.length?`<div class="table-scroll"><table><thead><tr><th>优先级</th><th>路由名称</th><th>匹配入站</th><th>转发目标</th><th>状态</th><th>当前命中</th><th>操作</th></tr></thead><tbody>${ordered.map(r=>`<tr><td><span class="count-badge mono">${r.priority}</span></td><td><div class="node-title">${esc(r.name)}</div><div class="route-sub mono">${r.id.slice(0,8)}</div></td><td><div class="tag-list">${r.inboundIDs.map(id=>`<span class="inbound-tag">${esc(node(id)?.name||'不存在')}</span>`).join('')}</div></td><td><div class="route-name">${icon('outbound',13)} ${r.direct?'直连 Telegram':esc(outbound(r.outboundID)?.name||'不存在')}</div><div class="route-sub">${r.direct?'使用本机网络':esc(outbound(r.outboundID)?.type||'')}</div></td><td>${status(r.enabled?'running':'paused',r.enabled?'已启用':'已停用')}</td><td>${Object.values(state.nodes).filter(v=>v.routeID===r.id).length} 个入站</td><td><div class="row-actions">${button('编辑','edit-route',r.id)}${button(r.enabled?'停用':'启用','toggle-route',r.id,'ghost')}${button('删除','delete-route',r.id,'ghost')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('还没有路由规则','创建入站后，选择直连 Telegram 或使用落地出口。')}${footer(ordered.length)}</section>${info('停用一条规则后，同一入站可能命中下一条规则。固定出口线路请只配置明确的转发规则。')}`;}
function renderOutbounds(){return `${heading('落地出口','接入现有代理服务，由路由规则决定哪些入站使用它。',button(icon('plus',14)+'添加出口','edit-outbound','','primary'),state.config.outbounds.length)}${state.config.outbounds.length?`<div class="outbound-grid">${state.config.outbounds.map(o=>{const h=state.health[o.id],count=state.config.routes.filter(r=>r.outboundID===o.id).length;return `<section class="outbound-card"><div class="outbound-card-top"><span class="node-icon">${icon('outbound',19)}</span><div><h3>${esc(o.name)}</h3><div class="route-sub">${o.type}</div></div>${status(!o.enabled?'paused':h?(h.healthy?'running':'offline'):'warning',!o.enabled?'已停用':h?(h.healthy?'探测成功':'探测失败'):'未测试')}</div><dl class="kv-list"><div><dt>代理地址</dt><dd class="mono">${esc(o.host)}:${o.port}</dd></div><div><dt>认证账号</dt><dd>${esc(o.account)||'无认证'}</dd></div><div><dt>TCP 隧道探测</dt><dd>${h?`${h.latencyMS} ms`:'尚未执行'}</dd></div><div><dt>链路加密</dt><dd>${o.type==='HTTPS'?'TLS · 验证证书':'由上层 TG 协议保护消息'}</dd></div></dl>${h?.error?`<p class="field-hint">${esc(h.error)}</p>`:''}<div class="outbound-card-bottom"><small>${count} 条路由引用</small><div>${button('测试','test-outbound',o.id)} ${button('编辑','edit-outbound',o.id,'ghost')} ${button('删除','delete-outbound',o.id,'ghost')}</div></div></section>`;}).join('')}</div>`:empty('添加第一个落地出口','支持 SOCKS5、HTTP CONNECT 和验证证书的 HTTPS 代理。',button(icon('plus',13)+'添加出口','edit-outbound','','primary'))}`;}
function renderUsers(){return `${heading('用户管理','每个入站使用独立密钥，用户总额度跨入站累计。',button(icon('plus',14)+'添加用户','edit-user','','primary'),state.config.users.length)}<section class="panel"><div class="panel-title-row"><h2>全部用户</h2></div>${state.config.users.length?`<div class="table-scroll"><table><thead><tr><th>用户</th><th>状态</th><th>入站权限</th><th>已用 / 总额度</th><th>到期日期</th><th>操作</th></tr></thead><tbody>${state.config.users.map(u=>{const used=total(usage('user',u.id)),expired=u.expires&&Date.parse(u.expires)<=Date.now(),exhausted=u.quotaBytes>0&&used>=u.quotaBytes;return `<tr><td><div class="user-name"><span class="user-avatar">${esc(u.name.slice(0,1))}</span><strong>${esc(u.name)}</strong></div></td><td>${status(!u.enabled?'paused':expired||exhausted?'warning':'running',!u.enabled?'已停用':expired?'已到期':exhausted?'额度耗尽':'正常')}</td><td>${credentials(null,u.id).length} 个入站</td><td>${bytes(used)} / ${u.quotaBytes?bytes(u.quotaBytes):'不限量'}${u.quotaBytes?`<div class="quota-track"><span style="width:${Math.min(100,used/u.quotaBytes*100)}%"></span></div>`:''}</td><td class="mono">${expiryDate(u.expires)||'长期有效'}</td><td><div class="row-actions">${button('编辑','edit-user',u.id)}${button('分配入站','assign-user',u.id,'ghost')}${button(icon('link',12)+'链接','user-links',u.id,'ghost')}</div></td></tr>`;}).join('')}</tbody></table></div>`:empty('还没有用户','创建用户后，为其分配入站并生成代理链接。')}${footer(state.config.users.length)}</section>`;}
function renderLogs(){return `${heading('活动日志','查看配置变更、探测结果与服务异常。',button(icon('refresh',13)+'刷新','refresh'))}<section class="panel"><div class="panel-title-row"><h2>最近事件</h2></div>${state.events?.length?`<div class="table-scroll"><table><thead><tr><th>时间 · 上海</th><th>级别</th><th>对象</th><th>内容</th></tr></thead><tbody>${state.events.map(e=>`<tr><td class="mono">${time(e.time)}</td><td><span class="log-level ${e.level}">${esc(e.level.toUpperCase())}</span></td><td>${esc(e.title)}</td><td class="log-detail">${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无活动记录')}${footer(state.events?.length||0)}</section>`;}
function liveChart(){if(history.length<2)return empty('正在收集实时速率','图表来自本次浏览器会话的实际采样。');const maximum=Math.max(1,...history.map(v=>Math.max(v.up,v.down)));const points=key=>history.map((v,i)=>`${30+i/(history.length-1)*590},${160-v[key]/maximum*125}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 650 200" role="img" aria-label="本次会话实际上下行速率"><g stroke="var(--line)" stroke-dasharray="3 4"><path d="M30 35H620M30 97H620M30 160H620"/></g><polyline points="${points('down')}" fill="none" stroke="var(--accent)" stroke-width="2"/><polyline points="${points('up')}" fill="none" stroke="var(--violet)" stroke-width="2"/><g fill="var(--muted)" font-size="10"><text x="30" y="188">${new Date(history[0].at).toLocaleTimeString()}</text><text x="565" y="188">现在</text></g></svg></div>`;}
function renderOverview(){return `${heading('运行概览','实时查看连接、流量和路由运行情况。',button(icon('refresh',13)+'刷新','refresh'))}${stats()}<div class="overview-grid"><section class="panel"><div class="panel-title-row"><div><h2>实时传输</h2><div class="subtext">当前浏览器会话 · 每 5 秒采样</div></div><div class="chart-legend"><span><i class="legend-dot"></i>下行</span><span><i class="legend-dot light"></i>上行</span></div></div>${liveChart()}</section><section class="panel"><div class="panel-title-row"><h2>最近活动</h2>${button('全部','go-logs','','link-button')}</div><div class="activity-list">${(state.events||[]).slice(0,4).map(e=>`<div class="activity-item"><span class="activity-icon">${icon(e.level==='error'?'alert':'check',13)}</span><div>${esc(e.title)}<small>${esc(e.detail)}</small></div></div>`).join('')||empty('暂无活动')}</div></section></div><section class="panel"><div class="panel-title-row"><h2>入站运行状态</h2>${button('管理入站','go-inbounds','','link-button')}</div>${nodesTable(state.config.inbounds.slice(0,5))}</section>`;}
function renderSettings(){return `${heading('面板设置','工作空间、外观与配置备份。')}<div class="settings-layout"><div class="settings-nav"><button class="active" type="button">${icon('settings',14)}基本设置</button></div><div class="panel" id="update-panel">${updateSection()}</div><form class="panel" id="settings-form"><section class="settings-section"><h2>工作空间</h2><p>名称显示在导航栏中。</p><div class="form-grid">${field('工作空间名称','workspace',state.config.settings.workspace,{full:true,required:true})}</div></section><section class="settings-section"><h2>Fake TLS 域名预设</h2><p>每行一个完整 HTTPS 网站域名，首项用于新入站默认值。修改预设不会更改已有入站或 TG 链接。</p><label class="form-field"><span class="field-label">候选域名（每行一个）</span><textarea name="tlsDomains" rows="4" aria-describedby="tls-presets-help">${esc(tlsPresets().join('\n'))}</textarea><p class="field-hint" id="tls-presets-help">最多 32 个，不带协议和端口；留空恢复内置列表。预设仅供选择，需经所选线路测试。</p></label></section><section class="settings-section"><h2>界面外观</h2><p>使用右上角的浅色 / 深色按钮即时切换，浏览器会记住选择。</p><h2>配置备份</h2><p>导出的 JSON 包含落地密码和用户密钥，请妥善保管。管理员登录密码不包含在内。</p>${button(icon('download',13)+'下载配置备份','backup')}</section><div id="form-error" class="form-error" role="alert"></div><div class="settings-bottom"><button class="primary" type="submit">保存设置</button></div></form></div>`;}
function render(){if(!state)return;remember($('#settings-form'));page=pageNames[location.hash.slice(1)]?location.hash.slice(1):'inbounds';$('#breadcrumb').textContent=pageNames[page];document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#content').innerHTML=(state.persistenceError?info('流量保存失败：'+esc(state.persistenceError),'alert'):'')+({overview:renderOverview,inbounds:renderInbounds,routes:renderRoutes,outbounds:renderOutbounds,users:renderUsers,logs:renderLogs,settings:renderSettings}[page])();if(page==='inbounds')$('#status-filter').value=filter;mountForm($('#settings-form'));if(page==='settings'&&!updateState&&updateChecked)loadUpdate().catch(error=>toast(error.message,true));}

function close(){remember($('form.dialog'));if(!$('.overlay'))return;$('#overlay-root').innerHTML='';document.body.style.overflow='';$('.shell').inert=false;$('.sidebar').inert=false;const target=previousFocus;previousFocus=null;if(target?.isConnected)target.focus();}
function overlay(html){
  if(dirty($('form.dialog'))){leave(()=>overlay(html));return;}
  const existing=$('[data-backdrop]'),focused=document.activeElement,action=focused?.dataset.action,id=focused?.dataset.id;
  if(!existing){previousFocus=focused;$('#overlay-root').innerHTML=`<div class="overlay" data-backdrop>${html}</div>`;}
  else{const template=document.createElement('template');template.innerHTML=html;const next=template.content.firstElementChild,current=existing.firstElementChild;if(current.tagName===next.tagName&&current.id===next.id){current.className=next.className;current.replaceChildren(...next.childNodes);}else{next.dataset.reused='true';existing.replaceChildren(next);}}
  document.body.style.overflow='hidden';$('.shell').inert=true;$('.sidebar').inert=true;mountForm($('form.dialog'));
  requestAnimationFrame(()=>{const modal=$('.dialog'),match=action?Array.from(modal.querySelectorAll('[data-action]')).find(b=>b.dataset.action===action&&b.dataset.id===id):null;(match||modal.querySelector('[autofocus]')||modal.querySelector('input:not([type="hidden"]),select')||modal.querySelector('button'))?.focus();});
}
function dialog(title,description,body,form='',submit='保存',extra=''){overlay(`<${form?'form':'section'} class="dialog" ${form?`id="${form}"`:''} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-header"><div><h2 id="dialog-title">${title}</h2><p>${description}</p></div><button type="button" class="icon-button ghost" aria-label="关闭对话框" data-action="close">${icon('close',16)}</button></div><div class="dialog-body">${body}<div id="form-error" class="form-error" role="alert"></div></div><div class="dialog-footer">${extra}${form?button('取消','close'):''}${form?`<button class="primary" type="submit">${submit}</button>`:button('完成','close','','primary')}</div></${form?'form':'section'}>`);}
function modeChoices(){return `<span class="field-label" style="margin-top:18px">应用方式</span><div class="switch-method"><label class="method-choice"><input type="radio" name="mode" value="smooth" checked>平滑切换<small>新连接使用新路由，旧连接继续。</small></label><label class="method-choice"><input type="radio" name="mode" value="immediate">立即切换<small>断开受影响连接，客户端重新连接。</small></label></div>`;}
function availablePort(){const occupied=new Set([...state.config.inbounds.map(n=>n.port),Number(location.port)]);for(let port=8443;port<=65535;port++)if(!occupied.has(port))return port;return 8443;}
async function detectEntry(form,replace){const input=form.elements.publicHost,initial=input.value,unchanged=JSON.stringify(formValues(form)),message=form.querySelector('#entry-source');if(message)message.textContent='正在识别服务器公网入口…';try{const result=await api('inbound-defaults');if(!form.isConnected)return;if(input.value===initial&&(replace||!input.value)){const pristine=!replace&&!dirty(form)&&JSON.stringify(formValues(form))===unchanged;input.value=result.host;if(pristine)formStates.get(form).baseline=JSON.stringify(formValues(form));else remember(form);}if(message)message.textContent='识别来源：'+result.source+'。可手动修改。';}catch(error){if(message?.isConnected)message.textContent=error.message;}}
function editInbound(id){const n=node(id)||{name:'',listenIP:'0.0.0.0',port:availablePort(),publicHost:!['localhost','127.0.0.1','[::1]'].includes(location.hostname)?location.hostname:'',tlsDomain:tlsPresets()[0]||'',enabled:true};dialog(id?'编辑入站':'新建入站','固定入口与用户密钥共同构成 TG 代理链接。',`<input type="hidden" name="entityID" value="${id||''}"><div class="form-grid">${field('入站名称','name',n.name,{full:true,required:true})}${field('监听 IP','listenIP',n.listenIP,{required:true,hint:'0.0.0.0 表示监听所有 IPv4 网卡。'})}${field('监听端口','port',n.port,{required:true,type:'number',min:1,max:65535})}${field('公开入口 IP / 域名','publicHost',n.publicHost,{full:true,required:true,placeholder:'用户实际连接的服务器地址',hint:'填写服务器公网 IP 或解析到该服务器的域名，不带协议和端口。'})}<div class="form-field full entry-detection">${button('自动识别 IP / 域名','detect-entry')}<p class="field-hint" id="entry-source" aria-live="polite">${n.publicHost?'已填入已有入口或当前面板地址，请核对。':'可从服务器识别公网入口。'}</p></div><label class="form-field full"><span class="field-label">选择伪装域名预设</span><select name="tlsPreset">${tlsPresets().map(domain=>`<option value="${esc(domain)}" ${domain===n.tlsDomain?'selected':''}>${esc(domain)}</option>`).join('')}<option value="@custom" ${!tlsPresets().includes(n.tlsDomain)?'selected':''}>手动填写</option></select></label>${field('Fake TLS 伪装域名','tlsDomain',n.tlsDomain,{full:true,required:true,placeholder:'例如 www.cloudflare.com',hint:'可选择上方预设，也可直接修改。候选域名未自动测试；无需拥有域名或申请证书，与面板域名无关。'})}${id?'':`<label class="form-field full"><span class="field-label">转发方式</span><select name="initialTarget"><option value="@direct">直连 Telegram（使用本机网络）</option>${state.config.outbounds.map(o=>`<option value="${o.id}" ${!o.enabled?'disabled':''}>经落地：${esc(o.name)} · ${o.type}</option>`).join('')}<option value="@later">稍后配置路由（暂时无法连接）</option></select><p class="field-hint">选择直连或落地时，会一起创建独立路由规则。</p></label>`}</div>${checkbox('启用入站','enabled',n.enabled)}${info(id?'修改入口、端口或伪装域名后，需要重新分发用户链接。':'创建后还需为用户分配入站凭据，才能使用专属 TG 链接。')}`,'inbound-form',id?'保存入站':'创建入站',id?button('删除入站','delete-inbound',id,'ghost'):'');if(!id){const form=$('#inbound-form');if(!form.elements.publicHost.value)detectEntry(form,false);}}
function editRoute(id,inboundIDs=[]){if(!state.config.inbounds.length){dialog('请先创建入站','路由按入站选择转发方式。',info('创建入站后，可选择直连 Telegram 或指定落地出口。'));return;}const r=route(id)||{name:'',inboundIDs,priority:100,outboundID:'',direct:true,enabled:true};dialog(id?'编辑路由规则':'新建路由规则','规则可以匹配多个入站；用户密钥不参与出口选择。',`<input type="hidden" name="entityID" value="${id||''}"><div class="form-grid">${field('规则名称','name',r.name,{full:true,required:true})}${field('优先级（数字越小越优先）','priority',r.priority,{type:'number',min:0,max:1000000,full:true,required:true})}<div class="form-field full"><span class="field-label">匹配入站</span><div class="assignment-list">${state.config.inbounds.map(n=>`<label><input type="checkbox" name="inboundIDs" value="${n.id}" ${r.inboundIDs.includes(n.id)?'checked':''}><span><strong>${esc(n.name)}</strong><small>:${n.port}</small></span></label>`).join('')}</div></div><label class="form-field full"><span class="field-label">转发目标</span><select name="outboundID"><option value="@direct" ${r.direct?'selected':''}>直连 Telegram（使用本机网络）</option>${state.config.outbounds.map(o=>`<option value="${o.id}" ${r.outboundID===o.id?'selected':''}>${esc(o.name)} · ${o.type}${!o.enabled?'（已停用）':''}</option>`).join('')}</select></label></div>${checkbox('启用规则','enabled',r.enabled)}${modeChoices()}${info('直连使用入站服务器的网络访问 Telegram。选择落地时，出口故障或停用均拒绝连接，不自动直连。修改会影响全部匹配入站。')}`,'route-form',id?'应用路由':'创建路由');}
function editOutbound(id){const o=outbound(id)||{name:'',type:'SOCKS5',host:'',port:1080,account:'',enabled:true};dialog(id?'编辑落地出口':'添加落地出口','填写你现有代理服务的连接信息。',`<input type="hidden" name="entityID" value="${id||''}"><div class="form-grid">${field('出口名称','name',o.name,{full:true,required:true})}<label class="form-field full"><span class="field-label">代理类型</span><select name="type">${['SOCKS5','HTTP','HTTPS'].map(v=>`<option ${o.type===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('IP / 域名','host',o.host,{required:true})}${field('端口','port',o.port,{required:true,type:'number',min:1,max:65535})}${field('用户名','account',o.account)}${field('密码','password','',{type:'password',autocomplete:'new-password',placeholder:id?'留空保留现有密码':'可选'})}</div>${id?checkbox('清除已有密码','clearPassword',false):''}${checkbox('启用出口','enabled',o.enabled)}${id?modeChoices():''}${info('HTTP 需要支持 CONNECT；HTTPS 会验证落地证书。出口故障不会自动回落直连。')}`,'outbound-form',id?'保存出口':'添加出口');}
function editUser(id){const u=user(id)||{name:'',quotaBytes:100*1024**3,expires:'',enabled:true};dialog(id?'编辑用户':'添加用户','用户总流量额度跨已分配的入站累计。',`<input type="hidden" name="entityID" value="${id||''}"><div class="form-grid">${field('用户名称','name',u.name,{full:true,required:true})}${field('总流量额度（GB）','quota',u.quotaBytes/1024**3,{type:'number',min:0,max:1048576,step:'any',hint:'0 表示不限量'})}${field('有效至（上海时区）','expires',expiryDate(u.expires),{type:'date',hint:'留空表示长期有效'})}</div>${checkbox('启用用户','enabled',u.enabled)}${info('到期、停用或额度耗尽会关闭已有连接。')}`,'user-form',id?'保存用户':'创建用户',id?button('删除用户','delete-user',id,'ghost'):'');}
function assignUser(id){const u=user(id);if(!state.config.inbounds.length){dialog('暂无入站','请先创建入站节点。',info('用户已保存。创建入站后可回来分配权限。'));return;}const selected=credentials(null,id).map(cr=>cr.inboundID);dialog('分配入站',esc(u.name),`<input type="hidden" name="entityID" value="${id}"><div class="assignment-list">${state.config.inbounds.map(n=>`<label><input type="checkbox" name="inboundIDs" value="${n.id}" ${selected.includes(n.id)?'checked':''}><span><strong>${esc(n.name)}</strong><small>${esc(n.publicHost)}:${n.port}</small></span></label>`).join('')}</div>${info('已分配入站的密钥保持不变。取消勾选会撤销凭据，重新分配将生成新密钥。')}`,'assign-form','保存权限');}
function manageNode(id,tab='config'){const n=node(id),rt=state.nodes[id]||{},r=route(rt.routeID),o=outbound(rt.outboundID),related=credentials(id);overlay(`<section class="dialog node-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-header"><span class="detail-heading-icon">${icon('inbound',20)}</span><div><h2 id="dialog-title">${esc(n.name)}</h2><div class="detail-meta">${status(rt.status||'offline')}<span class="mono muted">:${n.port}</span></div></div><button type="button" class="icon-button ghost" aria-label="关闭节点详情" data-action="close">${icon('close',16)}</button></div><div class="dialog-body"><div class="detail-tabs" role="tablist" aria-label="节点详情"><button type="button" role="tab" id="node-config-tab" aria-controls="node-detail-panel" aria-selected="${tab==='config'}" tabindex="${tab==='config'?0:-1}" class="${tab==='config'?'active':''}" data-action="manage" data-id="${id}">节点配置</button><button type="button" role="tab" id="node-users-tab" aria-controls="node-detail-panel" aria-selected="${tab==='users'}" tabindex="${tab==='users'?0:-1}" class="${tab==='users'?'active':''}" data-action="node-links" data-id="${id}">用户凭据 ${related.length}</button></div><div id="node-detail-panel" role="tabpanel" aria-labelledby="${tab==='config'?'node-config-tab':'node-users-tab'}">${tab==='config'?`<dl class="kv-list"><div><dt>公开入口</dt><dd class="mono">${esc(n.publicHost)}:${n.port}</dd></div><div><dt>监听地址</dt><dd class="mono">${esc(n.listenIP)}:${n.port}</dd></div><div><dt>代理模式</dt><dd>MTProto · Fake TLS</dd></div><div><dt>伪装域名</dt><dd class="mono">${esc(n.tlsDomain)}</dd></div></dl><div class="section-label">生效路由</div><div class="route-detail"><span class="node-icon">${icon('routes',16)}</span><div><div class="route-name">${esc(r?.name||'未匹配路由')}</div><div class="route-sub">${r?.direct?'直连 Telegram':o?esc(o.name):'暂无可用落地'}</div></div>${button(r?'编辑规则':'配置路由','node-route',id)}</div><div class="detail-stats"><div class="detail-stat">当前连接<strong>${rt.connections||0}</strong></div><div class="detail-stat">累计流量<strong>${bytes(total(usage('inbound',id)))}</strong></div></div>${rt.retiringConnections?info(`仍有 ${rt.retiringConnections} 条连接使用旧路由。`):''}`:`<div class="section-label">已分配用户${button(icon('plus',12)+'分配用户','assign-node',id,'ghost')}</div><div class="credential-list">${related.map(cr=>`<div class="credential-row"><span class="user-avatar">${esc(user(cr.userID)?.name.slice(0,1)||'?')}</span><div><strong>${esc(user(cr.userID)?.name||'未知用户')}</strong><small>${cr.enabled?'凭据已启用':'凭据已停用'}</small></div>${button('查看链接','credential-link',cr.id)}</div>`).join('')||empty('暂无用户凭据')}</div>${info('凭据只决定入站权限，出口由路由规则决定。')}`}</div></div><div class="dialog-footer">${button(n.enabled?'停用入站':'启用入站','toggle-inbound',id)}${button('编辑入站','edit-inbound',id,'primary')}</div></section>`);}
function assignNode(id){if(!state.config.users.length){editUser();return;}dialog('为入站分配用户',esc(node(id).name),`<input name="inboundID" type="hidden" value="${id}"><label class="form-field"><span class="field-label">选择用户</span><select name="userID">${state.config.users.filter(u=>!credentials(id,u.id).length).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label>${info('每位用户在此入站下生成独立的随机密钥。')}`,'credential-form','分配用户');}
async function showLink(id){
  const cr=state.config.credentials.find(v=>v.id===id),n=node(cr.inboundID),result=await api(`credentials/${id}/link`);
  dialog('TG 代理链接',`${esc(user(cr.userID)?.name)} · ${esc(n.name)}`,`<span class="field-label">用户专属链接</span><div class="code-box mono" id="proxy-link" tabindex="0">${esc(result.link)}</div>${result.warnings.length?info(result.warnings.map(esc).join('<br>'),'alert'):info('本地配置检查通过。尚未确认公网端口可达或真实 Telegram 客户端连接。')}<div class="section-label">线路检查 ${button('测试当前线路','test-inbound',n.id)}</div><div id="link-checks" aria-live="polite"><p class="field-hint">经当前路由测试 Telegram DC 与伪装网站的 TCP 443。不会代替客户端连接测试。</p></div><div class="callout-success"><span>${icon('shield',16)}</span><div>调整路由不改变此链接<p>保持入口、端口、Fake TLS 域名和用户密钥不变，即可继续使用原链接。</p></div></div>${info('链接包含用户密钥，请只分享给对应用户。若无法连接，请检查用户权限、路由、服务器时间，并放行 TG 入站端口的 TCP 防火墙和云安全组。')}`,'','',`<a class="telegram-link" href="${esc(result.webLink)}" target="_blank" rel="noopener noreferrer">在 Telegram 中打开</a>${button(icon('copy',13)+'复制链接','copy-link','','primary')}`);
}

function userLinks(id){const list=credentials(null,id);dialog('用户代理链接',esc(user(id).name),`<div class="credential-list">${list.map(cr=>`<div class="credential-row"><span class="node-icon">${icon('inbound',16)}</span><div><strong>${esc(node(cr.inboundID)?.name)}</strong><small>:${node(cr.inboundID)?.port}</small></div>${button('查看链接','credential-link',cr.id)}</div>`).join('')||empty('尚未分配入站','先为该用户分配入站权限。',button('分配入站','assign-user',id,'primary'))}</div>`);}
function explain(){dialog('路由与连接切换','TG 链接对应固定入站，出口由路由规则决定。',`<div class="routing-guide compact"><span>入站</span>${icon('arrow',16)}<span class="routing-guide-active">路由</span>${icon('arrow',16)}<span>落地</span></div><div class="section-label">平滑切换</div><p class="mode-description">新连接按新规则转发；已有连接继续使用旧出口，直到结束。需要保留旧落地服务。</p><div class="section-label">立即切换</div><p class="mode-description">关闭路由或出口变化所影响的连接，由 Telegram 重新连接。期间可能短暂显示连接中。</p>${info('停用用户或入站始终会关闭对应已有连接，不受平滑切换选项影响。')}`);}
function confirmDelete(kind,id){const names={inbounds:'入站',outbounds:'出口',routes:'路由',users:'用户'},v=state.config[kind].find(x=>x.id===id);dialog(`删除${names[kind]}`,esc(v.name),info(kind==='inbounds'?'会撤销此入站的全部凭据，并将它从路由中移除。':kind==='users'?'会撤销该用户全部凭据并关闭已有连接。':kind==='routes'?'会移除此规则并关闭转发关系变化的连接。没有其他匹配规则的入站将拒绝连接。':'引用此出口的路由需要先修改或删除。','alert'),'','',button(`确认删除${names[kind]}`,'confirm-delete',`${kind}:${id}`,'danger'));}

function showAuth(initialized){
  authEpoch++;close();drafts.clear();state=null;document.body.dataset.authenticated='false';$('#breadcrumb').textContent=initialized?'管理员登录':'首次设置';
  $('#content').innerHTML=`<div class="auth-layout"><section class="auth-intro" aria-label="TG Relay"><div class="auth-brand"><span class="brand-mark">${icon('send',25)}</span><div><strong>TG Relay</strong><span>Telegram 代理控制台</span></div></div><div class="eyebrow">ONE WORKSPACE. EVERY CONNECTION.</div><h1>连接有序，<br><span>管理从容。</span></h1><p>固定入口，独立路由。<br>把 Telegram 代理管理放在同一个工作台。</p><div class="auth-network" aria-label="转发结构：固定入站经独立路由，选择直连或落地"><div class="auth-network-node">${icon('inbound',22)}<strong>固定入站</strong><small>用户专属密钥</small></div><span class="auth-connector" aria-hidden="true">${icon('arrow',18)}</span><div class="auth-network-node selected">${icon('routes',22)}<strong>独立路由</strong><small>自由调整线路</small></div><span class="auth-connector" aria-hidden="true">${icon('arrow',18)}</span><div class="auth-network-node">${icon('outbound',22)}<strong>直连 / 落地</strong><small>明确选择出口</small></div></div><div class="auth-assurance">${icon('shield',17)}<span>独立凭据 · 流量配额 · 灵活路由</span></div></section><form class="panel auth-card" id="${initialized?'login-form':'setup-form'}"><div class="auth-card-icon">${icon('lock',22)}</div><div class="auth-card-eyebrow">${initialized?'WORKSPACE ACCESS':'GET STARTED'}</div><h2>${initialized?'欢迎回来':'创建管理员'}</h2><p class="page-description">${initialized?'登录管理面板，继续管理你的连接。':'首次设置仅允许从服务器本机完成。'}</p><div class="form-grid">${field('用户名','username',initialized?'':'admin',{required:true,full:true,autocomplete:'username'})}${field('密码','password','',{type:'password',required:true,full:true,autocomplete:initialized?'current-password':'new-password',hint:initialized?'':'至少 6 个字符，支持 6 位数字。'})}${initialized?'':field('确认密码','confirmation','',{type:'password',required:true,full:true,autocomplete:'new-password'})}</div><div id="form-error" class="form-error" role="alert"></div><button class="primary auth-submit" type="submit"><span>${initialized?'登录面板':'创建并进入面板'}</span>${icon('arrow',17)}</button><div class="auth-recovery">${icon('info',16)}<p>忘记账号或密码？<br><span>在服务器运行 <code>tg</code>，选择重置管理员账号和密码。</span></p></div></form></div>`;
}

async function save(kind,id,data,mode='smooth'){return api(`${kind}${id?'/'+id:''}?mode=${mode}`,{method:id?'PATCH':'POST',body:JSON.stringify(data)});}
function formError(form,error){const target=form.querySelector('[role="alert"]');if(target?.isConnected)target.textContent=error.message;else toast(error.message,true);}
document.addEventListener('submit',async event=>{
  event.preventDefault();if(busy)return;const form=event.target,d=new FormData(form),id=d.get('entityID')||'',mode=d.get('mode')||'smooth',enabled=d.has('enabled');busy=true;form.setAttribute('aria-busy','true');form.querySelectorAll('button[type="submit"]').forEach(b=>b.disabled=true);
  try{
    if(form.id==='setup-form'||form.id==='login-form'){if(form.id==='setup-form'&&d.get('password')!==d.get('confirmation'))throw new Error('两次输入的密码不一致。');await api(form.id==='setup-form'?'setup':'login',{method:'POST',body:JSON.stringify({username:d.get('username'),password:d.get('password')})});await refresh();return;}
    let after=null;
    switch(form.id){
      case 'inbound-form':{const target=d.get('initialTarget');await save('inbounds',id,{name:d.get('name').trim(),listenIP:d.get('listenIP').trim(),port:Number(d.get('port')),publicHost:d.get('publicHost').trim(),tlsDomain:d.get('tlsDomain').trim(),enabled,...(!id&&target!=='@later'?{initialRoute:{direct:target==='@direct',outboundID:target==='@direct'?'':target}}:{})});break;}
      case 'route-form':{const inboundIDs=d.getAll('inboundIDs');if(!inboundIDs.length)throw new Error('请至少选择一个匹配入站。');await save('routes',id,{name:d.get('name').trim(),inboundIDs,direct:d.get('outboundID')==='@direct',outboundID:d.get('outboundID')==='@direct'?'':d.get('outboundID'),priority:Number(d.get('priority')),enabled},mode);break;}
      case 'outbound-form':{const data={name:d.get('name').trim(),type:d.get('type'),host:d.get('host').trim(),port:Number(d.get('port')),account:d.get('account'),enabled};if(!id||d.get('password')||d.has('clearPassword'))data.password=d.has('clearPassword')?'':d.get('password');await save('outbounds',id,data,mode);break;}
      case 'user-form':{const quota=Number(d.get('quota'));const result=await save('users',id,{name:d.get('name').trim(),quotaBytes:Math.round(quota*1024**3),expires:dateToExpiry(d.get('expires')),enabled});if(!id)after=()=>assignUser(result.id);break;}
      case 'assign-form':await api(`users/${id}/assign`,{method:'POST',body:JSON.stringify({inboundIDs:d.getAll('inboundIDs')})});break;
      case 'credential-form':if(!d.get('userID'))throw new Error('没有尚未分配的用户。');await save('credentials','',{userID:d.get('userID'),inboundID:d.get('inboundID'),enabled:true});break;
      case 'settings-form':await api('settings',{method:'PATCH',body:JSON.stringify({workspace:d.get('workspace').trim(),tlsDomains:[...new Set(d.get('tlsDomains').split(/\r?\n/).map(v=>v.trim().toLowerCase()).filter(Boolean))]})});break;
      default:return;
    }
    const meta=formStates.get(form);if(meta){drafts.delete(meta.key);meta.baseline=JSON.stringify(formValues(form));}close();await refresh();toast('配置已保存并应用');after?.();
  }catch(error){formError(form,error);}finally{busy=false;form.removeAttribute('aria-busy');form.querySelectorAll('button[type="submit"]').forEach(b=>b.disabled=false);}
});
document.addEventListener('click',async event=>{
  if(event.target.closest('#unsaved-guard'))return;
  if(event.target.matches('[data-backdrop]')){if(!$('form.dialog'))close();return;}
  if(busy&&event.target.closest('[data-action],[data-page]')){event.preventDefault();return;}
  const nav=event.target.closest('[data-page]');if(nav){event.preventDefault();leave(()=>{query='';filter='all';$('.sidebar').classList.remove('mobile-open');close();if(nav.dataset.page===page)render();else location.hash=nav.dataset.page;});return;}
  const control=event.target.closest('[data-action]');if(!control)return;const {action,id}=control.dataset;
  try{
    if(action.startsWith('go-')){leave(()=>{close();location.hash=action.slice(3);});return;}
    if(action.startsWith('delete-')){confirmDelete({inbound:'inbounds',outbound:'outbounds',route:'routes',user:'users'}[action.slice(7)],id);return;}
    switch(action){
      case 'close':leave(close);break;
      case 'detect-entry':control.disabled=true;await detectEntry($('#inbound-form'),true);break;
      case 'check-update':control.disabled=true;control.textContent='检查中…';await loadUpdate(true);if(updateState.error)toast(updateState.error,true);else toast(updateState.available?'发现新版本 '+updateState.latest:'版本检查完成');break;
      case 'open-update':dialog('更新到 '+esc(updateState.latest),'安装包来自 wstimin/tg-relay 官方仓库。',info('下载和 SHA256 校验通过后将重启 TG Relay，已有 TG 连接会短暂断开。端口、管理员账号密码、证书、路由、用户密钥及流量全部保留，不需要重新设置。')+info('新版启动检查失败时恢复原程序。更新成功后需重新登录面板。'),'','',button('确认更新','start-update','','primary'));break;
      case 'start-update':{if(dirty($('#settings-form'))){toast('请先保存设置或放弃未保存的修改，再更新程序。',true);return;}control.disabled=true;const target=updateState.latest;updateState=await api('update',{method:'POST',body:JSON.stringify({version:target,confirm:true})});close();paintUpdate();watchUpdate();toast('更新任务已提交');break;}

      case 'refresh':leave(()=>refresh().then(()=>toast('运行状态已更新')).catch(error=>toast(error.message,true)));break;
      case 'edit-inbound':editInbound(id);break;
      case 'edit-outbound':editOutbound(id);break;
      case 'edit-route':editRoute(id);break;
      case 'edit-user':editUser(id);break;
      case 'assign-user':assignUser(id);break;
      case 'assign-node':assignNode(id);break;
      case 'manage':manageNode(id);break;
      case 'node-links':manageNode(id,'users');break;
      case 'node-route':{const rid=state.nodes[id]?.routeID;editRoute(rid||'',[id]);break;}
      case 'credential-link':await showLink(id);break;
      case 'user-links':userLinks(id);break;
      case 'copy-link':try{await navigator.clipboard.writeText($('#proxy-link').textContent);toast('代理链接已复制');}catch{toast('复制未获允许，请选择文本手动复制。',true);}break;
      case 'toggle-inbound':{const n=node(id);if(n.enabled){dialog('停用入站',esc(n.name),info('将拒绝新连接并关闭此入站全部已有连接。','alert'),'','',button('确认停用','confirm-stop',id,'danger'));}else{await save('inbounds',id,{enabled:true});close();await refresh();toast('入站已启用');}break;}
      case 'confirm-stop':await save('inbounds',id,{enabled:false});close();await refresh();toast('入站已停用');break;
      case 'toggle-route':{const r=route(id);await save('routes',id,{enabled:!r.enabled},'immediate');await refresh();toast('规则状态已更新，受影响的连接已关闭');break;}
      case 'confirm-delete':{const [kind,entityID]=id.split(':');await api(`${kind}/${entityID}`,{method:'DELETE'});close();await refresh();toast('配置已删除');break;}
      case 'test-inbound':{const target=$('#link-checks');control.disabled=true;control.textContent='测试中…';const checks=await api(`inbounds/${id}/test`,{method:'POST'});if(target?.isConnected)target.innerHTML=checks.map((h,i)=>info(`${i?'伪装网站':'Telegram DC'} TCP：${h.healthy?`已连通 · ${h.latencyMS} ms`:esc(h.error)}`,h.healthy?'check':'alert')).join('')+info('测试仅验证服务器侧 TCP 线路；公网入口、客户端网络和完整 Telegram 协议连接仍需实际验证。');break;}
      case 'test-outbound':{control.disabled=true;control.textContent='测试中…';const h=await api(`outbounds/${id}/test`,{method:'POST'});await refresh();toast(h.healthy?`TCP 隧道已连接 · ${h.latencyMS} ms`:h.error,!h.healthy);break;}
      case 'explain':explain();break;
      case 'backup':{const response=await fetch('/api/backup',{credentials:'same-origin'});if(!response.ok)throw new Error('备份下载失败。');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tg-relay-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
      case 'logout':leave(()=>api('logout',{method:'POST'}).then(()=>showAuth(true)).catch(error=>toast(error.message,true)));break;
    }
  }catch(error){toast(error.message,true);}finally{if(control.isConnected){control.disabled=false;if(action==='test-outbound')control.textContent='测试';if(action==='test-inbound')control.textContent='测试当前线路';if(action==='check-update')control.textContent='检查更新';}}
});
document.addEventListener('input',event=>{if(event.target.name==='tlsDomain'){const form=event.target.form;form.elements.tlsPreset.value=tlsPresets().includes(event.target.value)?event.target.value:'@custom';}const form=event.target.form;if(formStates.has(form)){if(dirty(form))remember(form);else drafts.delete(formStates.get(form).key);}if(event.target.id==='search-input'){query=event.target.value;$('#node-results').innerHTML=nodeResults();}});
document.addEventListener('change',event=>{if(event.target.name==='tlsPreset'){const form=event.target.form;if(event.target.value!=='@custom')form.elements.tlsDomain.value=event.target.value;else form.elements.tlsDomain.focus();}remember(event.target.form);if(formStates.has(event.target.form)&&!dirty(event.target.form))drafts.delete(formStates.get(event.target.form).key);if(event.target.id==='status-filter'){filter=event.target.value;$('#node-results').innerHTML=nodeResults();}});
document.addEventListener('keydown',event=>{document.documentElement.dataset.input='keyboard';const tabs=event.target.closest('.detail-tabs');if(tabs&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const items=Array.from(tabs.querySelectorAll('[role="tab"]')),current=items.indexOf(event.target),next=event.key==='Home'?0:event.key==='End'?items.length-1:(current+(event.key==='ArrowRight'?1:-1)+items.length)%items.length;items[next].focus();items[next].click();return;}const modal=$('#unsaved-guard .dialog')||$('.dialog');if(!modal)return;if(event.key==='Escape'){event.preventDefault();const stay=$('[data-action="stay-draft"]');if(stay)stay.click();else leave(close);return;}if(event.key==='Tab'){const focusable=Array.from(modal.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled):not([type="hidden"]),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')).filter(el=>el.getClientRects().length),first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
document.addEventListener('pointerdown',()=>document.documentElement.dataset.input='pointer');
$('#mobile-menu').addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('mobile-open');$('#mobile-menu').setAttribute('aria-expanded',String(open));});
$('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#content').focus();});
window.addEventListener('beforeunload',event=>{if(drafts.size||dirty($('form.dialog'))||dirty($('#settings-form'))){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{remember($('#settings-form'));close();if(state)render();window.scrollTo(0,0);});
setInterval(async()=>{if(!state||busy||updating()||dirty($('#settings-form'))||$('.overlay')||document.visibilityState!=='visible'||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;try{await refresh();}catch(error){toast(error.message,true);}},5000);
try{const auth=await api('auth');showVersion(auth.version);if(auth.authenticated)await refresh();else showAuth(auth.initialized);}catch(error){document.body.dataset.authenticated='false';$('#content').innerHTML=empty('无法连接 TG Relay 服务',esc(error.message));}
